local f=game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts") local o=f:FindFirstChild("AnimeIncrementalGame") if o then o:Destroy() end local s=Instance.new("LocalScript") s.Name="AnimeIncrementalGame" s.Source="--[[\n\t=====================================================================\n\t ANIME INCREMENTAL GAME  (a LocalScript that builds the WHOLE game UI)\n\t=====================================================================\n\t WHERE THIS LIVES:  StarterPlayer > StarterPlayerScripts > AnimeIncrementalGame\n\t WHAT IT DOES:      Builds every button, label and animation with code.\n\t                    No images yet: every ImageLabel is blank so you can\n\t                    paste your own image ids in later.\n\n\t HOW TO READ THIS FILE (top to bottom):\n\t   1. SERVICES      -> tools Roblox gives us (tweening, players, etc.)\n\t   2. SETTINGS      -> numbers you can change (prices, chances, names)\n\t   3. PLAYER DATA   -> what the player owns (coins, gems, level...)\n\t   4. HELPERS       -> small reusable functions (make a button, animate)\n\t   5. BUILD THE UI  -> actually creates the screen\n\t   6. GAME LOGIC    -> attacking, rewards, shop, eggs\n\t   7. START         -> turns everything on\n\n\t TIP: \"--\" starts a comment. Roblox ignores comments, they are only for you.\n\t=====================================================================\n]]\n\n---------------------------------------------------------------------------\n-- 1. SERVICES\n-- A \"service\" is a built-in Roblox toolbox. We grab them once and keep them\n-- in variables so we can use them anywhere below.\n---------------------------------------------------------------------------\nlocal Players = game:GetService(\"Players\")                     -- gives us the player who is playing\nlocal TweenService = game:GetService(\"TweenService\")           -- smoothly animates properties (size, color, position)\nlocal RunService = game:GetService(\"RunService\")               -- lets us run code every single frame\nlocal MarketplaceService = game:GetService(\"MarketplaceService\") -- handles Robux purchases (gamepasses)\n\nlocal player = Players.LocalPlayer                 -- \"LocalPlayer\" = the person on THIS computer\nlocal playerGui = player:WaitForChild(\"PlayerGui\") -- the folder where on-screen UI must go (we wait until it exists)\n\n---------------------------------------------------------------------------\n-- 2. SETTINGS  (change these freely!)\n---------------------------------------------------------------------------\n\n-- FONTS: cartoony built-in Roblox fonts\nlocal TITLE_FONT = Enum.Font.LuckiestGuy -- big chunky comic font for titles\nlocal TEXT_FONT = Enum.Font.FredokaOne   -- round bubbly font for normal text\n\n-- COLORS: Color3.fromRGB(red, green, blue) each number goes from 0 to 255\nlocal COLORS = {\n\tOutline = Color3.fromRGB(25, 15, 45),    -- dark purple-black, used for the thick cartoon outlines\n\tWhite = Color3.fromRGB(255, 255, 255),   -- plain white\n\tCoin = Color3.fromRGB(255, 205, 40),     -- gold yellow for coins\n\tGem = Color3.fromRGB(80, 220, 255),      -- light blue for gems\n\tGreen = Color3.fromRGB(90, 230, 90),     -- happy green (buttons, XP)\n\tRed = Color3.fromRGB(255, 70, 90),       -- red (enemy health)\n\tPink = Color3.fromRGB(255, 100, 200),    -- hot pink\n\tPurple = Color3.fromRGB(150, 80, 255),   -- bright purple\n\tOrange = Color3.fromRGB(255, 150, 40),   -- orange\n\tPanel = Color3.fromRGB(255, 245, 225),   -- creamy paper color for windows\n}\n\n-- GAMEPASSES: put your real gamepass id numbers here (0 = not set up yet)\nlocal GAMEPASSES = {\n\t{ Name = \"2x Coins\", Description = \"Double every coin you earn!\", Id = 0, Color = COLORS.Coin },  -- one gamepass entry\n\t{ Name = \"2x Damage\", Description = \"Hit twice as hard!\", Id = 0, Color = COLORS.Red },           -- another gamepass entry\n\t{ Name = \"VIP\", Description = \"+50% gems & a cool title!\", Id = 0, Color = COLORS.Purple },       -- another gamepass entry\n}\n\n-- STORY MODE: each chapter has 10 stages. Stage 10 of every chapter is a BOSS.\nlocal STAGES_PER_CHAPTER = 10 -- how many stages fit in one chapter\nlocal CHAPTERS = {\n\t{ Name = \"Slime Meadow\", Enemies = { \"Green Slime\", \"Bouncy Blob\", \"Jelly Cube\" }, Boss = \"KING SLIME\", Color = Color3.fromRGB(110, 220, 110) },\n\t{ Name = \"Spooky Forest\", Enemies = { \"Angry Shroom\", \"Bat Goblin\", \"Ghost Fox\" }, Boss = \"ANCIENT TREANT\", Color = Color3.fromRGB(140, 90, 200) },\n\t{ Name = \"Lava Volcano\", Enemies = { \"Fire Imp\", \"Magma Crab\", \"Ash Golem\" }, Boss = \"MAGMA DRAGON\", Color = Color3.fromRGB(255, 110, 60) },\n\t{ Name = \"Sky Castle\", Enemies = { \"Cloud Knight\", \"Storm Hawk\", \"Sky Wizard\" }, Boss = \"STORM TITAN\", Color = Color3.fromRGB(90, 180, 255) },\n}\n\n-- RARITIES: each rarity gets its own color\nlocal RARITY_COLORS = {\n\tCommon = Color3.fromRGB(200, 200, 200),    -- grey\n\tRare = Color3.fromRGB(70, 160, 255),       -- blue\n\tEpic = Color3.fromRGB(180, 80, 255),       -- purple\n\tLegendary = Color3.fromRGB(255, 190, 30),  -- gold\n\tMythic = Color3.fromRGB(255, 60, 120),     -- hot pink-red\n}\n\n-- CHARACTERS you can hatch from eggs.\n-- Chance = how likely (all chances added together = 100, so it reads like %)\n-- Power  = how much extra damage per second this character adds to your team\nlocal CHARACTERS = {\n\t{ Name = \"Ninja Kid\", Rarity = \"Common\", Chance = 35, Power = 1 },\n\t{ Name = \"Slime Tamer\", Rarity = \"Common\", Chance = 25, Power = 2 },\n\t{ Name = \"Fire Mage\", Rarity = \"Rare\", Chance = 20, Power = 5 },\n\t{ Name = \"Thunder Samurai\", Rarity = \"Epic\", Chance = 12, Power = 12 },\n\t{ Name = \"Shadow King\", Rarity = \"Legendary\", Chance = 6, Power = 40 },\n\t{ Name = \"Celestial Goddess\", Rarity = \"Mythic\", Chance = 2, Power = 150 },\n}\n\n-- EGGS you can buy\nlocal EGGS = {\n\t{ Name = \"Basic Egg\", Price = 100, Currency = \"Coins\", Rolls = 1, Color = Color3.fromRGB(255, 240, 200) }, -- costs coins, 1 roll\n\t{ Name = \"Golden Egg\", Price = 15, Currency = \"Gems\", Rolls = 2, Color = COLORS.Coin },                   -- costs gems, rolls TWICE and keeps the best\n}\n\n-- UPGRADES in the shop. Cost goes up by 1.5x every time you buy one.\nlocal UPGRADES = {\n\t{ Name = \"Sharper Sword\", Description = \"+1 Click Damage\", Stat = \"ClickPower\", Amount = 1, BaseCost = 25, Currency = \"Coins\", Bought = 0 },\n\t{ Name = \"Hero Training\", Description = \"+2 Auto Damage /sec\", Stat = \"AutoPower\", Amount = 2, BaseCost = 60, Currency = \"Coins\", Bought = 0 },\n\t{ Name = \"Gem Blade\", Description = \"+10 Click Damage\", Stat = \"ClickPower\", Amount = 10, BaseCost = 10, Currency = \"Gems\", Bought = 0 },\n}\n\n---------------------------------------------------------------------------\n-- 3. PLAYER DATA  (everything the player owns, kept in one table)\n-- A \"table\" is like a box with labeled slots: Data.Coins, Data.Gems, ...\n-- NOTE: this does NOT save yet. When you leave, it resets. (Saving needs a\n-- server Script + DataStoreService, a good next step!)\n---------------------------------------------------------------------------\nlocal Data = {\n\tCoins = 0,        -- money from beating enemies\n\tGems = 0,         -- rare money from bosses\n\tLevel = 1,        -- player level\n\tXP = 0,           -- experience toward the next level\n\tStage = 1,        -- which story stage you are on\n\tClickPower = 1,   -- damage per click\n\tAutoPower = 1,    -- damage your hero does by itself every second\n\tTeam = {},        -- list of characters you hatched\n\tOwnsPass = {},    -- which gamepasses you own, e.g. OwnsPass[\"2x Coins\"] = true\n}\n\n-- The current enemy's health (changes during the fight)\nlocal enemyHP = 10      -- health right now\nlocal enemyMaxHP = 10   -- health when it was full\n\n---------------------------------------------------------------------------\n-- 4. HELPERS  (small reusable functions)\n--\n-- WHAT IS A FUNCTION?  A recipe you write once and use many times.\n--   local function Add(a, b)   <- \"a\" and \"b\" are PARAMETERS: blank slots\n--       return a + b              you fill in when you USE the function.\n--   end\n--   Add(2, 3)  --> gives back 5   (here a = 2 and b = 3)\n-- The NAME of a parameter is just a nickname. You know what it does by\n-- reading how it is used inside the function (and the comment above it!).\n---------------------------------------------------------------------------\n\n-- make(className, properties, parent)\n--   className  = what kind of thing to create, e.g. \"Frame\" or \"TextButton\"\n--   properties = a table of settings, e.g. { Size = ..., Text = \"Hi\" }\n--   parent     = where to put it (what it lives inside)\n-- Example: make(\"TextLabel\", { Text = \"Hello\" }, someFrame)\nlocal function make(className, properties, parent)\n\tlocal object = Instance.new(className)      -- create the new object\n\tfor propertyName, value in pairs(properties) do -- go through every setting in the table one by one...\n\t\tobject[propertyName] = value            -- ...and apply it (same as writing object.Text = \"Hello\")\n\tend\n\tobject.Parent = parent                      -- put it inside its parent LAST (faster + avoids flicker)\n\treturn object                               -- hand the new object back so we can keep using it\nend\n\n-- addCorner(object, radius): makes the corners round. radius = how round (in pixels)\nlocal function addCorner(object, radius)\n\treturn make(\"UICorner\", { CornerRadius = UDim.new(0, radius or 16) }, object) -- \"radius or 16\" = use 16 if no radius was given\nend\n\n-- addOutline(object, thickness): thick dark cartoon border around a box\nlocal function addOutline(object, thickness)\n\treturn make(\"UIStroke\", {\n\t\tThickness = thickness or 4,                          -- how thick the line is\n\t\tColor = COLORS.Outline,                              -- dark outline color\n\t\tApplyStrokeMode = Enum.ApplyStrokeMode.Border,       -- \"Border\" = outline the BOX, not the text\n\t\tLineJoinMode = Enum.LineJoinMode.Round,              -- rounded corners on the outline\n\t}, object)\nend\n\n-- addTextOutline(object, thickness): thick dark outline around TEXT letters\nlocal function addTextOutline(object, thickness)\n\treturn make(\"UIStroke\", {\n\t\tThickness = thickness or 3,                          -- outline thickness\n\t\tColor = COLORS.Outline,                              -- dark color\n\t\tApplyStrokeMode = Enum.ApplyStrokeMode.Contextual,   -- \"Contextual\" = outline the TEXT\n\t}, object)\nend\n\n-- addGradient(object, topColor, bottomColor): smooth color fade from top to bottom\nlocal function addGradient(object, topColor, bottomColor)\n\treturn make(\"UIGradient\", {\n\t\tColor = ColorSequence.new(topColor, bottomColor), -- fade from the first color to the second\n\t\tRotation = 90,                                     -- 90 degrees = top to bottom\n\t}, object)\nend\n\n-- getScale(object): every animated thing gets a \"UIScale\" so we can grow/shrink it\nlocal function getScale(object)\n\tlocal scale = object:FindFirstChildOfClass(\"UIScale\") -- look for one that already exists\n\tif not scale then                                     -- if there is none yet...\n\t\tscale = make(\"UIScale\", { Scale = 1 }, object)    -- ...make one (1 = normal size)\n\tend\n\treturn scale                                          -- give it back\nend\n\n-- tween(object, seconds, goals, style, direction): smoothly animate properties\n-- Example: tween(myFrame, 0.5, { BackgroundTransparency = 1 })  -> fades out over half a second\nlocal function tween(object, seconds, goals, style, direction)\n\tlocal info = TweenInfo.new(                         -- TweenInfo = HOW the animation moves\n\t\tseconds,                                        -- how long it takes\n\t\tstyle or Enum.EasingStyle.Quad,                 -- the motion shape (Back/Elastic/Bounce feel cartoony!)\n\t\tdirection or Enum.EasingDirection.Out           -- slow down at the end\n\t)\n\tlocal animation = TweenService:Create(object, info, goals) -- build the animation\n\tanimation:Play()                                    -- start it\n\treturn animation                                    -- give it back in case we want to wait for it\nend\n\n-- pop(object): quick cartoon \"boing!\" - grows big then bounces back\nlocal function pop(object, bigness)\n\tlocal scale = getScale(object)                                        -- get the UIScale\n\tscale.Scale = bigness or 1.25                                         -- instantly make it bigger\n\ttween(scale, 0.4, { Scale = 1 }, Enum.EasingStyle.Elastic)            -- wobble back to normal size\nend\n\n-- shake(object): wiggle something left and right (used when the enemy gets hit)\nlocal function shake(object)\n\tlocal startRotation = 0                         -- normal straight rotation\n\tfor i = 1, 4 do                                 -- repeat 4 times (i counts 1, 2, 3, 4)\n\t\tlocal angle = (i % 2 == 0) and 6 or -6      -- even numbers tilt right (+6), odd tilt left (-6)\n\t\tobject.Rotation = angle                     -- tilt it\n\t\ttask.wait(0.03)                             -- wait a tiny moment\n\tend\n\tobject.Rotation = startRotation                 -- straighten it back up\nend\n\n-- formatNumber(n): turns 1500 into \"1.5K\", 2000000 into \"2M\" so numbers stay short\nlocal function formatNumber(n)\n\tn = math.floor(n)                                             -- remove decimals\n\tif n >= 1e9 then return string.format(\"%.1fB\", n / 1e9) end   -- billions  (1e9 = 1,000,000,000)\n\tif n >= 1e6 then return string.format(\"%.1fM\", n / 1e6) end   -- millions\n\tif n >= 1e3 then return string.format(\"%.1fK\", n / 1e3) end   -- thousands\n\treturn tostring(n)                                            -- small numbers stay as they are\nend\n\n-- makeBouncy(button): makes a button squish and grow when you hover/click it\nlocal function makeBouncy(button)\n\tlocal scale = getScale(button)                                                    -- the UIScale we animate\n\tbutton.MouseEnter:Connect(function()                                              -- when the mouse moves ONTO the button...\n\t\ttween(scale, 0.2, { Scale = 1.08 }, Enum.EasingStyle.Back)                    -- ...grow a bit\n\tend)\n\tbutton.MouseLeave:Connect(function()                                              -- when the mouse moves OFF...\n\t\ttween(scale, 0.2, { Scale = 1 }, Enum.EasingStyle.Back)                       -- ...go back to normal\n\tend)\n\tbutton.MouseButton1Down:Connect(function()                                        -- when you PRESS down...\n\t\ttween(scale, 0.08, { Scale = 0.88 })                                          -- ...squish small\n\tend)\n\tbutton.MouseButton1Up:Connect(function()                                          -- when you LET GO...\n\t\ttween(scale, 0.35, { Scale = 1.08 }, Enum.EasingStyle.Elastic)                -- ...spring back with a wobble\n\tend)\nend\n\n-- makeButton(text, color, size, position, parent): a chunky cartoon button\nlocal function makeButton(text, color, size, position, parent)\n\tlocal button = make(\"TextButton\", {\n\t\tText = text,                                -- words on the button\n\t\tFont = TITLE_FONT,                          -- comic font\n\t\tTextScaled = true,                          -- text auto-sizes to fit\n\t\tTextColor3 = COLORS.White,                  -- white letters\n\t\tBackgroundColor3 = COLORS.White,            -- white so the gradient below shows its true colors\n\t\tSize = size,                                -- how big\n\t\tPosition = position,                        -- where\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),        -- position is measured from the CENTER of the button\n\t\tAutoButtonColor = false,                    -- turn off Roblox's boring grey hover effect\n\t}, parent)\n\taddCorner(button, 14)                           -- round corners\n\taddOutline(button, 4)                           -- thick outline around the box\n\taddTextOutline(button, 3)                       -- thick outline around the letters\n\taddGradient(button, color, color:Lerp(COLORS.Outline, 0.35)) -- top = color, bottom = slightly darker (Lerp = mix two colors)\n\tmake(\"UIPadding\", {                             -- keep the text away from the edges\n\t\tPaddingTop = UDim.new(0.15, 0), PaddingBottom = UDim.new(0.15, 0),\n\t\tPaddingLeft = UDim.new(0.08, 0), PaddingRight = UDim.new(0.08, 0),\n\t}, button)\n\tmakeBouncy(button)                              -- add the squishy animation\n\treturn button                                   -- give the button back\nend\n\n-- makeLabel(text, size, position, parent, color): outlined cartoon text\nlocal function makeLabel(text, size, position, parent, color)\n\tlocal label = make(\"TextLabel\", {\n\t\tText = text,                                -- the words\n\t\tFont = TITLE_FONT,                          -- comic font\n\t\tTextScaled = true,                          -- auto size\n\t\tTextColor3 = color or COLORS.White,         -- color (white if none given)\n\t\tBackgroundTransparency = 1,                 -- no background box, just text\n\t\tSize = size,                                -- how big\n\t\tPosition = position,                        -- where\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),        -- measured from the center\n\t}, parent)\n\taddTextOutline(label, 3)                        -- outline the letters\n\treturn label                                    -- give it back\nend\n\n-- makeBar(size, position, parent, fillColor): a health/xp bar. Returns (background, fill, text)\nlocal function makeBar(size, position, parent, fillColor)\n\tlocal back = make(\"Frame\", {\n\t\tSize = size, Position = position,                        -- size and place\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),                     -- measured from center\n\t\tBackgroundColor3 = Color3.fromRGB(50, 35, 70),           -- dark empty part of the bar\n\t}, parent)\n\taddCorner(back, 10)                                          -- round\n\taddOutline(back, 3)                                          -- outline\n\tlocal fill = make(\"Frame\", {\n\t\tSize = UDim2.new(1, 0, 1, 0),                            -- starts full (1 = 100% wide)\n\t\tBackgroundColor3 = COLORS.White,                         -- white so gradient colors show\n\t}, back)\n\taddCorner(fill, 10)                                          -- round\n\taddGradient(fill, fillColor, fillColor:Lerp(COLORS.Outline, 0.3)) -- shiny gradient\n\tlocal text = makeLabel(\"\", UDim2.new(1, 0, 0.8, 0), UDim2.new(0.5, 0, 0.5, 0), back) -- text on top of the bar\n\ttext.ZIndex = 3                                              -- ZIndex = draw order, higher = on top\n\treturn back, fill, text                                      -- a function can give back MORE than one thing!\nend\n\n---------------------------------------------------------------------------\n-- 5. BUILD THE UI\n---------------------------------------------------------------------------\n\n-- ScreenGui = the \"canvas\" that holds all 2D UI on the screen\nlocal gui = make(\"ScreenGui\", {\n\tName = \"AnimeIncrementalGui\",   -- name you will see in the Explorer while playing\n\tResetOnSpawn = false,           -- keep the UI when your character respawns\n\tIgnoreGuiInset = true,          -- cover the whole screen (including the top bar area)\n\tZIndexBehavior = Enum.ZIndexBehavior.Sibling, -- simpler draw ordering\n}, playerGui)\n\n-- BACKGROUND: big colorful gradient that slowly spins\nlocal background = make(\"Frame\", { Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = COLORS.White }, gui) -- fills the screen\nlocal backgroundGradient = make(\"UIGradient\", {\n\tColor = ColorSequence.new({                                         -- a gradient with 3 color stops\n\t\tColorSequenceKeypoint.new(0, Color3.fromRGB(120, 70, 255)),     -- 0%  = purple\n\t\tColorSequenceKeypoint.new(0.5, Color3.fromRGB(255, 90, 190)),   -- 50% = pink\n\t\tColorSequenceKeypoint.new(1, Color3.fromRGB(255, 180, 60)),     -- 100% = orange\n\t}),\n}, background)\n\n-- Floating bubbles in the background (pure decoration, makes it feel alive)\nfor i = 1, 14 do                                                  -- make 14 bubbles (i goes 1, 2, 3 ... 14)\n\tlocal bubbleSize = math.random(30, 110)                       -- random size in pixels\n\tlocal bubble = make(\"Frame\", {\n\t\tSize = UDim2.new(0, bubbleSize, 0, bubbleSize),           -- square (corner makes it a circle)\n\t\tPosition = UDim2.new(math.random(), 0, 1.2, 0),           -- random left/right spot, start BELOW the screen\n\t\tBackgroundColor3 = COLORS.White,                          -- white\n\t\tBackgroundTransparency = 0.8,                             -- mostly see-through\n\t}, background)\n\taddCorner(bubble, 999)                                        -- huge radius = perfect circle\n\tlocal loop = TweenInfo.new(math.random(8, 16), Enum.EasingStyle.Linear, Enum.EasingDirection.In, -1) -- -1 = repeat forever\n\ttask.delay(math.random() * 8, function()                      -- start each bubble at a random time so they spread out\n\t\tTweenService:Create(bubble, loop, { Position = UDim2.new(bubble.Position.X.Scale, 0, -0.2, 0) }):Play() -- float to the top\n\tend)\nend\n\n-- TOP BAR: coins, gems, level\nlocal topBar = make(\"Frame\", {\n\tSize = UDim2.new(0.7, 0, 0.09, 0),           -- 70% of screen wide, 9% tall\n\tPosition = UDim2.new(0.5, 0, 0.02, 0),       -- centered, near the top\n\tAnchorPoint = Vector2.new(0.5, 0),           -- measured from the top-middle\n\tBackgroundTransparency = 1,                  -- invisible holder\n}, gui)\nmake(\"UIListLayout\", {                           -- auto-arranges children side by side\n\tFillDirection = Enum.FillDirection.Horizontal,\n\tHorizontalAlignment = Enum.HorizontalAlignment.Center,\n\tPadding = UDim.new(0.02, 0),                 -- gap between pills\n}, topBar)\n\n-- makePill(icon, color): one rounded stat box like \"COINS 120\". Returns the text label inside.\nlocal function makePill(icon, color)\n\tlocal pill = make(\"Frame\", { Size = UDim2.new(0.3, 0, 1, 0), BackgroundColor3 = COLORS.White }, topBar) -- the box\n\taddCorner(pill, 999)                                                  -- pill shape\n\taddOutline(pill, 4)                                                   -- outline\n\taddGradient(pill, color, color:Lerp(COLORS.Outline, 0.4))             -- gradient\n\tlocal iconBox = make(\"TextLabel\", {                                   -- the round \"icon\" circle on the left\n\t\tSize = UDim2.new(1, 0, 1.3, 0), SizeConstraint = Enum.SizeConstraint.RelativeYY, -- RelativeYY = keep it a square based on height\n\t\tPosition = UDim2.new(0, -10, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5),\n\t\tBackgroundColor3 = color, Text = icon, Font = TITLE_FONT, TextScaled = true, TextColor3 = COLORS.White,\n\t}, pill)\n\taddCorner(iconBox, 999)                                               -- circle\n\taddOutline(iconBox, 4)                                                -- outline\n\taddTextOutline(iconBox, 2)                                            -- letter outline\n\tlocal text = makeLabel(\"0\", UDim2.new(0.65, 0, 0.75, 0), UDim2.new(0.6, 0, 0.5, 0), pill) -- the number\n\treturn text                                                           -- give back the label so we can change its text later\nend\n\nlocal coinsText = makePill(\"$\", COLORS.Coin)   -- coins pill\nlocal gemsText = makePill(\"G\", COLORS.Gem)     -- gems pill\nlocal levelText = makePill(\"LV\", COLORS.Green) -- level pill\n\n-- XP bar right under the top bar\nlocal _, xpFill, xpText = makeBar(UDim2.new(0.4, 0, 0.035, 0), UDim2.new(0.5, 0, 0.14, 0), gui, COLORS.Green) -- \"_\" = we don't need the first returned thing\n\n-- STAGE BANNER: shows chapter + stage\nlocal stageBanner = make(\"Frame\", {\n\tSize = UDim2.new(0.42, 0, 0.08, 0), Position = UDim2.new(0.5, 0, 0.22, 0), -- size / place\n\tAnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = COLORS.White,\n\tRotation = -2,                                                            -- slightly tilted = more cartoony\n}, gui)\naddCorner(stageBanner, 18)                                                    -- round\naddOutline(stageBanner, 5)                                                    -- outline\nlocal stageGradient = addGradient(stageBanner, COLORS.Orange, COLORS.Pink)    -- gradient (we recolor it per chapter)\nlocal stageText = makeLabel(\"STAGE 1\", UDim2.new(0.92, 0, 0.8, 0), UDim2.new(0.5, 0, 0.5, 0), stageBanner) -- the words\n\n-- makeFighterCard(side, title, color): a big card for a fighter (hero or enemy).\n--   side  = 0.2 for the left side of the screen, 0.8 for the right side\n-- Returns a table with all the important parts so we can change them later.\nlocal function makeFighterCard(side, title, color)\n\tlocal card = make(\"Frame\", {\n\t\tSize = UDim2.new(0.24, 0, 0.5, 0), Position = UDim2.new(side, 0, 0.56, 0), -- size / place\n\t\tAnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = COLORS.White,\n\t}, gui)\n\taddCorner(card, 24)                                                      -- round\n\taddOutline(card, 6)                                                      -- extra-thick outline\n\tlocal gradient = addGradient(card, color, color:Lerp(COLORS.Outline, 0.45)) -- gradient\n\n\tlocal nameText = makeLabel(title, UDim2.new(0.9, 0, 0.12, 0), UDim2.new(0.5, 0, 0.09, 0), card) -- name at the top\n\n\t-- The picture spot. BLANK for now: put \"rbxassetid://YOUR_ID\" in Image later!\n\tlocal picture = make(\"ImageLabel\", {\n\t\tImage = \"\",                                            -- <-- paste your image id here later\n\t\tSize = UDim2.new(0.75, 0, 0.6, 0), Position = UDim2.new(0.5, 0, 0.48, 0),\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tBackgroundColor3 = COLORS.White, BackgroundTransparency = 0.6, -- see-through white \"empty slot\" look\n\t\tScaleType = Enum.ScaleType.Fit,                        -- images keep their shape\n\t}, card)\n\taddCorner(picture, 20)                                     -- round\n\tmake(\"UIStroke\", { Thickness = 3, Color = COLORS.White, Transparency = 0.3 }, picture) -- soft white border\n\n\t-- White flash overlay (we flash it when this fighter gets hit)\n\tlocal flash = make(\"Frame\", { Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = COLORS.White, BackgroundTransparency = 1, ZIndex = 5 }, picture)\n\taddCorner(flash, 20)                                       -- round like the picture\n\n\t-- Idle \"breathing\" bob: the picture gently floats up and down forever\n\tlocal bob = TweenInfo.new(1.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true) -- -1 = forever, true = go back and forth\n\tTweenService:Create(picture, bob, { Position = UDim2.new(0.5, 0, 0.45, 0) }):Play()\n\n\tlocal back, fill, barText = makeBar(UDim2.new(0.85, 0, 0.09, 0), UDim2.new(0.5, 0, 0.88, 0), card, COLORS.Red) -- health / stat bar\n\n\t-- Put all the parts in one table so we can use card.Picture, card.Name, etc.\n\treturn { Frame = card, Gradient = gradient, Name = nameText, Picture = picture, Flash = flash, BarBack = back, BarFill = fill, BarText = barText }\nend\n\nlocal hero = makeFighterCard(0.2, player.DisplayName, COLORS.Green) -- LEFT side: your character (uses your Roblox name)\nhero.BarFill.Size = UDim2.new(1, 0, 1, 0)                           -- hero bar is always full\nhero.BarFill:FindFirstChildOfClass(\"UIGradient\").Color = ColorSequence.new(COLORS.Gem, COLORS.Purple) -- recolor hero's bar blue/purple\nlocal enemy = makeFighterCard(0.8, \"SLIME\", COLORS.Red)             -- RIGHT side: the enemy\n\n-- Big \"VS\" in the middle that pulses forever\nlocal vsText = makeLabel(\"VS\", UDim2.new(0.14, 0, 0.14, 0), UDim2.new(0.5, 0, 0.47, 0), gui, COLORS.Coin)\nvsText.Rotation = -8                                                -- tilted\nlocal vsPulse = TweenInfo.new(0.6, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true) -- forever, back and forth\nTweenService:Create(getScale(vsText), vsPulse, { Scale = 1.2 }):Play()\n\n-- Team power text under VS\nlocal teamText = makeLabel(\"TEAM POWER: 0\", UDim2.new(0.25, 0, 0.045, 0), UDim2.new(0.5, 0, 0.6, 0), gui)\n\n-- BIG ATTACK BUTTON in the middle-bottom with a spinning rainbow\nlocal attackButton = makeButton(\"ATTACK!\", COLORS.Red, UDim2.new(0.22, 0, 0.12, 0), UDim2.new(0.5, 0, 0.75, 0), gui)\nattackButton:FindFirstChildOfClass(\"UIGradient\"):Destroy()          -- remove the normal gradient...\nlocal rainbow = make(\"UIGradient\", {                                -- ...and give it a rainbow instead\n\tColor = ColorSequence.new({\n\t\tColorSequenceKeypoint.new(0, Color3.fromRGB(255, 70, 90)),\n\t\tColorSequenceKeypoint.new(0.33, Color3.fromRGB(255, 190, 40)),\n\t\tColorSequenceKeypoint.new(0.66, Color3.fromRGB(255, 80, 200)),\n\t\tColorSequenceKeypoint.new(1, Color3.fromRGB(255, 70, 90)),\n\t}),\n}, attackButton)\n\n-- BOTTOM MENU buttons\nlocal shopButton = makeButton(\"SHOP\", COLORS.Coin, UDim2.new(0.13, 0, 0.09, 0), UDim2.new(0.3, 0, 0.92, 0), gui)\nlocal eggsButton = makeButton(\"EGGS\", COLORS.Pink, UDim2.new(0.13, 0, 0.09, 0), UDim2.new(0.5, 0, 0.92, 0), gui)\nlocal storyButton = makeButton(\"STORY\", COLORS.Purple, UDim2.new(0.13, 0, 0.09, 0), UDim2.new(0.7, 0, 0.92, 0), gui)\n\n-- TOAST: a little message that slides in from the top (\"Not enough coins!\")\nlocal toast = makeLabel(\"\", UDim2.new(0.5, 0, 0.06, 0), UDim2.new(0.5, 0, -0.1, 0), gui, COLORS.Coin)\ntoast.ZIndex = 50                                                   -- always on top\nlocal function showToast(message, color)\n\ttoast.Text = message                                            -- set the message\n\ttoast.TextColor3 = color or COLORS.Coin                         -- set the color\n\ttoast.Position = UDim2.new(0.5, 0, -0.1, 0)                     -- start above the screen\n\ttween(toast, 0.4, { Position = UDim2.new(0.5, 0, 0.3, 0) }, Enum.EasingStyle.Back) -- drop in\n\ttask.delay(1.6, function()                                      -- after 1.6 seconds...\n\t\ttween(toast, 0.3, { Position = UDim2.new(0.5, 0, -0.1, 0) }, Enum.EasingStyle.Back, Enum.EasingDirection.In) -- ...fly back out\n\tend)\nend\n\n-- POPUP WINDOWS (Shop, Eggs, Story all use this same recipe)\n-- makePanel(title, color): returns (panel, content) - content is a scrolling list to put items in\nlocal openPanelFrame = nil                                          -- remembers which window is open (nil = none)\n\nlocal function makePanel(title, color)\n\tlocal panel = make(\"Frame\", {\n\t\tSize = UDim2.new(0.55, 0, 0.65, 0), Position = UDim2.new(0.5, 0, 0.5, 0), -- big centered window\n\t\tAnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = COLORS.Panel,\n\t\tVisible = false, ZIndex = 20,                                             -- hidden at the start\n\t}, gui)\n\taddCorner(panel, 26)                                            -- round\n\taddOutline(panel, 7)                                            -- extra thick outline\n\tlocal header = make(\"Frame\", {                                  -- colored header strip\n\t\tSize = UDim2.new(1, 0, 0.16, 0), BackgroundColor3 = COLORS.White, ZIndex = 21,\n\t}, panel)\n\taddCorner(header, 26)                                           -- round\n\taddOutline(header, 5)                                           -- outline\n\taddGradient(header, color, color:Lerp(COLORS.Outline, 0.4))     -- gradient\n\tlocal titleText = makeLabel(title, UDim2.new(0.6, 0, 0.8, 0), UDim2.new(0.5, 0, 0.5, 0), header) -- title\n\ttitleText.ZIndex = 22\n\n\tlocal closeButton = makeButton(\"X\", COLORS.Red, UDim2.new(0.09, 0, 0.13, 0), UDim2.new(0.97, 0, 0.03, 0), panel) -- close button in the corner\n\tcloseButton.SizeConstraint = Enum.SizeConstraint.RelativeYY    -- keep it square\n\tcloseButton.Size = UDim2.new(0.13, 0, 0.13, 0)\n\tcloseButton.ZIndex = 25\n\tcloseButton.MouseButton1Click:Connect(function()                -- when X is clicked...\n\t\ttween(getScale(panel), 0.2, { Scale = 0 }, Enum.EasingStyle.Back, Enum.EasingDirection.In) -- ...shrink away\n\t\ttask.delay(0.2, function() panel.Visible = false end)       -- ...then hide it\n\t\topenPanelFrame = nil                                        -- no window open now\n\tend)\n\n\tlocal content = make(\"ScrollingFrame\", {                        -- scrolling list area\n\t\tSize = UDim2.new(0.94, 0, 0.78, 0), Position = UDim2.new(0.5, 0, 0.58, 0),\n\t\tAnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1, ZIndex = 21,\n\t\tScrollBarThickness = 10, ScrollBarImageColor3 = COLORS.Outline,\n\t\tCanvasSize = UDim2.new(0, 0, 0, 0),                         -- starts empty...\n\t\tAutomaticCanvasSize = Enum.AutomaticSize.Y,                 -- ...and grows when we add items\n\t}, panel)\n\treturn panel, content                                           -- give back both\nend\n\n-- openPanel(panel): show a window with a bouncy \"pop open\" animation\nlocal function openPanel(panel)\n\tif openPanelFrame and openPanelFrame ~= panel then              -- if a DIFFERENT window is already open...\n\t\topenPanelFrame.Visible = false                              -- ...hide it first\n\tend\n\topenPanelFrame = panel                                          -- remember this one is open\n\tpanel.Visible = true                                            -- show it\n\tlocal scale = getScale(panel)                                   -- its UIScale\n\tscale.Scale = 0                                                 -- start tiny\n\ttween(scale, 0.45, { Scale = 1 }, Enum.EasingStyle.Back)        -- pop open with an overshoot\nend\n\n-- makeItemRow(parent, title, subtitle, color, buttonText): one row in a list. Returns (row, buyButton)\nlocal function makeItemRow(parent, title, subtitle, color, buttonText)\n\tlocal row = make(\"Frame\", { Size = UDim2.new(1, -16, 0, 90), BackgroundColor3 = COLORS.White, ZIndex = 22 }, parent) -- 90 pixels tall\n\taddCorner(row, 18)                                              -- round\n\taddOutline(row, 4)                                              -- outline\n\taddGradient(row, color, color:Lerp(COLORS.Outline, 0.3))        -- gradient\n\tlocal icon = make(\"ImageLabel\", {                               -- blank icon spot (put an image later)\n\t\tImage = \"\", Size = UDim2.new(0, 70, 0, 70), Position = UDim2.new(0, 10, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5),\n\t\tBackgroundColor3 = COLORS.White, BackgroundTransparency = 0.5, ZIndex = 23,\n\t}, row)\n\taddCorner(icon, 14)                                             -- round\n\tlocal titleLabel = makeLabel(title, UDim2.new(0.45, 0, 0.42, 0), UDim2.new(0, 95, 0.3, 0), row) -- title\n\ttitleLabel.AnchorPoint = Vector2.new(0, 0.5)                    -- measure from the left edge\n\ttitleLabel.TextXAlignment = Enum.TextXAlignment.Left            -- text hugs the left\n\ttitleLabel.ZIndex = 23\n\tlocal subLabel = makeLabel(subtitle, UDim2.new(0.45, 0, 0.3, 0), UDim2.new(0, 95, 0.72, 0), row) -- smaller description\n\tsubLabel.Font = TEXT_FONT\n\tsubLabel.AnchorPoint = Vector2.new(0, 0.5)\n\tsubLabel.TextXAlignment = Enum.TextXAlignment.Left\n\tsubLabel.ZIndex = 23\n\tlocal buyButton = makeButton(buttonText, COLORS.Green, UDim2.new(0.28, 0, 0.7, 0), UDim2.new(0.84, 0, 0.5, 0), row) -- buy button\n\tbuyButton.ZIndex = 24\n\treturn row, buyButton, subLabel                                 -- give back the parts\nend\n\n-- Build the three windows\nlocal shopPanel, shopList = makePanel(\"SHOP\", COLORS.Coin)\nlocal eggPanel, eggList = makePanel(\"EGGS\", COLORS.Pink)\nlocal storyPanel, storyList = makePanel(\"STORY MODE\", COLORS.Purple)\nfor _, list in ipairs({ shopList, eggList, storyList }) do          -- for each of the 3 lists...\n\tmake(\"UIListLayout\", { Padding = UDim.new(0, 10), SortOrder = Enum.SortOrder.LayoutOrder }, list) -- ...stack rows top to bottom\n\tmake(\"UIPadding\", { PaddingTop = UDim.new(0, 8), PaddingLeft = UDim.new(0, 8) }, list)              -- ...with some breathing room\nend\n\n---------------------------------------------------------------------------\n-- 6. GAME LOGIC\n---------------------------------------------------------------------------\n\n-- getTeamPower(): adds up the Power of every character you hatched\nlocal function getTeamPower()\n\tlocal total = 0                                   -- start at zero\n\tfor _, character in ipairs(Data.Team) do          -- look at each character in your team\n\t\ttotal = total + character.Power               -- add its power to the total\n\tend\n\treturn total                                      -- give back the sum\nend\n--[[\n\tHOW \"for _, character in ipairs(Data.Team) do\" WORKS:\n\t  - Data.Team is a LIST like { NinjaKid, FireMage, NinjaKid }\n\t  - ipairs walks through it in order: 1st item, 2nd item, 3rd item...\n\t  - each time, it gives us TWO things: the position (1, 2, 3...) and the item\n\t  - we named the position \"_\" (means \"I don't care about it\")\n\t  - we named the item \"character\" so we can use character.Power\n\t  - \"pairs\" is the same idea but for tables with NAMED slots (like Data.Coins)\n]]\n\n-- getClickDamage(): how much one click hits for\nlocal function getClickDamage()\n\tlocal damage = Data.ClickPower + (Data.Level - 1)  -- base + 1 extra per level\n\tif Data.OwnsPass[\"2x Damage\"] then                 -- if you own the 2x Damage gamepass...\n\t\tdamage = damage * 2                            -- ...double it\n\tend\n\treturn damage\nend\n\n-- getAutoDamage(): how much your hero (and team) hit every second automatically\nlocal function getAutoDamage()\n\tlocal damage = Data.AutoPower + getTeamPower()     -- hero's own power + all hatched characters\n\tif Data.OwnsPass[\"2x Damage\"] then damage = damage * 2 end -- gamepass bonus\n\treturn damage\nend\n\n-- getChapter(stage): which chapter a stage belongs to (1-10 = chapter 1, 11-20 = chapter 2, ...)\nlocal function getChapter(stage)\n\tlocal number = math.floor((stage - 1) / STAGES_PER_CHAPTER) + 1 -- e.g. stage 15 -> floor(14/10)+1 = 2\n\treturn CHAPTERS[math.min(number, #CHAPTERS)], number            -- \"#CHAPTERS\" = how many chapters exist. After the last one it keeps using the last chapter (endless!)\nend\n\n-- isBossStage(stage): true if this is the 10th, 20th, 30th... stage\nlocal function isBossStage(stage)\n\treturn stage % STAGES_PER_CHAPTER == 0           -- \"%\" = remainder after dividing. 20 % 10 = 0, so stage 20 is a boss\nend\n\n-- updateUI(): refresh every number on screen. Call it whenever Data changes.\nlocal function updateUI()\n\tcoinsText.Text = formatNumber(Data.Coins)                          -- coins number\n\tgemsText.Text = formatNumber(Data.Gems)                            -- gems number\n\tlevelText.Text = \"LEVEL \" .. Data.Level                            -- \"..\" glues text together: \"LEVEL \" .. 5 = \"LEVEL 5\"\n\tlocal xpNeeded = Data.Level * 10                                   -- XP needed grows each level\n\ttween(xpFill, 0.3, { Size = UDim2.new(math.clamp(Data.XP / xpNeeded, 0, 1), 0, 1, 0) }) -- fill bar = XP / needed (clamp keeps it between 0 and 1)\n\txpText.Text = \"XP \" .. Data.XP .. \" / \" .. xpNeeded                -- e.g. \"XP 4 / 10\"\n\thero.BarText.Text = \"DMG \" .. formatNumber(getClickDamage()) .. \"  |  AUTO \" .. formatNumber(getAutoDamage()) .. \"/s\" -- hero stats\n\tteamText.Text = \"TEAM POWER: \" .. formatNumber(getTeamPower()) .. \"  (\" .. #Data.Team .. \" heroes)\" -- team info\n\tlocal hpPercent = math.clamp(enemyHP / enemyMaxHP, 0, 1)           -- 0 to 1 how much health is left\n\ttween(enemy.BarFill, 0.15, { Size = UDim2.new(hpPercent, 0, 1, 0) }) -- shrink the health bar smoothly\n\tenemy.BarText.Text = formatNumber(math.max(enemyHP, 0)) .. \" / \" .. formatNumber(enemyMaxHP) -- \"HP / MaxHP\"\nend\n\n-- spawnEnemy(): create the enemy for the current stage\nlocal function spawnEnemy()\n\tlocal chapter, chapterNumber = getChapter(Data.Stage)              -- which chapter we're in\n\tlocal boss = isBossStage(Data.Stage)                               -- is this a boss?\n\tenemyMaxHP = math.floor(10 * (1.35 ^ (Data.Stage - 1)))            -- HP grows 35% each stage (\"^\" = to the power of)\n\tif boss then enemyMaxHP = enemyMaxHP * 5 end                       -- bosses have 5x health\n\tenemyHP = enemyMaxHP                                               -- start at full health\n\n\tif boss then\n\t\tenemy.Name.Text = chapter.Boss                                 -- boss name\n\t\tenemy.Name.TextColor3 = COLORS.Coin                            -- gold name for bosses\n\telse\n\t\tenemy.Name.Text = chapter.Enemies[math.random(1, #chapter.Enemies)] -- pick a random enemy name from the chapter list\n\t\tenemy.Name.TextColor3 = COLORS.White\n\tend\n\tenemy.Gradient.Color = ColorSequence.new(chapter.Color, chapter.Color:Lerp(COLORS.Outline, 0.45)) -- card color = chapter color\n\tstageGradient.Color = ColorSequence.new(chapter.Color, COLORS.Pink)                               -- banner color too\n\n\tlocal stageInChapter = (Data.Stage - 1) % STAGES_PER_CHAPTER + 1   -- 1 to 10 inside this chapter\n\tstageText.Text = \"CH.\" .. chapterNumber .. \" \" .. chapter.Name .. \" - \" .. (boss and \"BOSS!\" or (\"STAGE \" .. stageInChapter))\n\tpop(stageBanner, 1.3)                                              -- boing the banner\n\n\t-- New enemy \"drops in\": start tiny and spin, then bounce to full size\n\tlocal scale = getScale(enemy.Frame)\n\tscale.Scale = 0\n\tenemy.Frame.Rotation = 25\n\ttween(scale, 0.5, { Scale = boss and 1.1 or 1 }, Enum.EasingStyle.Back) -- bosses are a bit bigger\n\ttween(enemy.Frame, 0.5, { Rotation = 0 }, Enum.EasingStyle.Back)\n\tupdateUI()\nend\n\n-- floatingText(text, color, parent): a number that pops up, floats away and fades\nlocal function floatingText(text, color, parent)\n\tlocal label = makeLabel(text, UDim2.new(0.5, 0, 0.15, 0), UDim2.new(0.3 + math.random() * 0.4, 0, 0.45, 0), parent, color) -- random spot\n\tlabel.ZIndex = 10                                                          -- above everything on the card\n\tlabel.Rotation = math.random(-20, 20)                                      -- random tilt = more fun\n\tpop(label, 1.8)                                                            -- burst in big\n\ttween(label, 0.9, { Position = label.Position - UDim2.new(0, 0, 0.35, 0), TextTransparency = 1 }) -- float up + fade\n\ttween(label:FindFirstChildOfClass(\"UIStroke\"), 0.9, { Transparency = 1 })  -- fade the outline too\n\ttask.delay(0.9, function() label:Destroy() end)                            -- delete it when done (keeps the game fast)\nend\n\n-- addXP(amount): gives XP and levels up when the bar is full\nlocal function addXP(amount)\n\tData.XP = Data.XP + amount                                 -- add XP\n\twhile Data.XP >= Data.Level * 10 do                        -- \"while\" repeats as long as this is true (you might level up twice!)\n\t\tData.XP = Data.XP - Data.Level * 10                    -- spend the XP\n\t\tData.Level = Data.Level + 1                            -- level up!\n\t\tshowToast(\"LEVEL UP!  LV \" .. Data.Level, COLORS.Green)\n\t\tpop(levelText.Parent, 1.5)                             -- boing the level pill (.Parent = the pill the text sits in)\n\tend\nend\n\nlocal defeating = false -- a \"lock\" so the enemy can't die twice at the same time\n\n-- defeatEnemy(): enemy reached 0 HP -> give rewards and go to the next stage\nlocal function defeatEnemy()\n\tif defeating then return end                               -- already handling a defeat? stop here\n\tdefeating = true                                           -- lock\n\n\tlocal boss = isBossStage(Data.Stage)\n\tlocal coins = math.floor(5 * (1.25 ^ (Data.Stage - 1)))    -- coins grow 25% each stage\n\tif boss then coins = coins * 10 end                        -- bosses give 10x coins\n\tif Data.OwnsPass[\"2x Coins\"] then coins = coins * 2 end    -- gamepass bonus\n\tData.Coins = Data.Coins + coins\n\tfloatingText(\"+\" .. formatNumber(coins) .. \" COINS\", COLORS.Coin, enemy.Frame)\n\tpop(coinsText.Parent, 1.4)                                 -- boing the coins pill\n\n\tif boss then                                               -- bosses also give gems\n\t\tlocal gems = 5 + math.floor(Data.Stage / 10) * 2       -- more gems for later bosses\n\t\tif Data.OwnsPass[\"VIP\"] then gems = math.floor(gems * 1.5) end\n\t\tData.Gems = Data.Gems + gems\n\t\tshowToast(\"BOSS DEFEATED!  +\" .. gems .. \" GEMS\", COLORS.Gem)\n\t\tpop(gemsText.Parent, 1.5)\n\telseif math.random(1, 10) == 1 then                        -- 1 in 10 chance for a bonus gem from normal enemies\n\t\tData.Gems = Data.Gems + 1\n\t\tfloatingText(\"+1 GEM\", COLORS.Gem, enemy.Frame)\n\tend\n\n\taddXP(boss and 10 or 2)                                    -- XP reward (\"a and b or c\" = if a then b else c)\n\n\t-- Death animation: spin and shrink away\n\ttween(getScale(enemy.Frame), 0.35, { Scale = 0 }, Enum.EasingStyle.Back, Enum.EasingDirection.In)\n\ttween(enemy.Frame, 0.35, { Rotation = -40 })\n\ttask.wait(0.4)                                             -- wait for the animation to finish\n\n\tData.Stage = Data.Stage + 1                                -- next stage\n\tspawnEnemy()                                               -- bring in the new enemy\n\tdefeating = false                                          -- unlock\nend\n\n-- damageEnemy(amount, color): hurt the enemy with juicy effects\nlocal function damageEnemy(amount, color)\n\tif defeating then return end                               -- don't hit a dying enemy\n\tenemyHP = enemyHP - amount                                 -- lower health\n\tfloatingText(\"-\" .. formatNumber(amount), color or COLORS.White, enemy.Frame) -- show the damage number\n\tenemy.Flash.BackgroundTransparency = 0.2                   -- flash white...\n\ttween(enemy.Flash, 0.25, { BackgroundTransparency = 1 })   -- ...and fade the flash away\n\ttask.spawn(shake, enemy.Frame)                             -- wiggle (task.spawn runs it at the same time as the rest of the code)\n\tupdateUI()\n\tif enemyHP <= 0 then                                       -- out of health?\n\t\ttask.spawn(defeatEnemy)                                -- defeat it\n\tend\nend\n\n-- heroLunge(): hero jumps forward toward the enemy then back\nlocal function heroLunge()\n\tlocal frame = hero.Frame\n\ttween(frame, 0.08, { Position = UDim2.new(0.25, 0, 0.56, 0), Rotation = 6 }) -- jump right + lean\n\ttask.delay(0.1, function()\n\t\ttween(frame, 0.3, { Position = UDim2.new(0.2, 0, 0.56, 0), Rotation = 0 }, Enum.EasingStyle.Back) -- bounce back\n\tend)\nend\n\n-- When the ATTACK button is clicked\nattackButton.MouseButton1Click:Connect(function()\n\theroLunge()                                                -- hero animation\n\tdamageEnemy(getClickDamage(), COLORS.Coin)                 -- hit with click damage (yellow numbers)\nend)\n--[[\n\tWHAT IS \":Connect(function() ... end)\"?\n\t  attackButton.MouseButton1Click is an EVENT = \"something that happens\".\n\t  :Connect( ) says \"when that happens, run THIS function\".\n\t  The function has no name because we only need it right here.\n]]\n\n---------------------------------------------------------------------------\n-- SHOP\n---------------------------------------------------------------------------\n\n-- getUpgradeCost(upgrade): price goes up 1.5x for every one you already bought\nlocal function getUpgradeCost(upgrade)\n\treturn math.floor(upgrade.BaseCost * (1.5 ^ upgrade.Bought))\nend\n\n-- trySpend(currency, price): returns true and takes the money if you can afford it\nlocal function trySpend(currency, price)\n\tif Data[currency] >= price then                  -- Data[\"Coins\"] is the same as Data.Coins\n\t\tData[currency] = Data[currency] - price      -- take the money\n\t\treturn true                                  -- success!\n\tend\n\tshowToast(\"NOT ENOUGH \" .. string.upper(currency) .. \"!\", COLORS.Red) -- tell the player\n\treturn false                                     -- failed\nend\n\nmakeLabel(\"UPGRADES\", UDim2.new(1, -16, 0, 40), UDim2.new(0, 0, 0, 0), shopList, COLORS.Purple).ZIndex = 22 -- section title\n\nfor _, upgrade in ipairs(UPGRADES) do                                -- one row per upgrade\n\tlocal color = upgrade.Currency == \"Gems\" and COLORS.Gem or COLORS.Orange -- gem upgrades are blue\n\tlocal _, buyButton, subLabel = makeItemRow(shopList, upgrade.Name, upgrade.Description, color, \"\")\n\tlocal function refresh()                                          -- updates the price on the button\n\t\tbuyButton.Text = formatNumber(getUpgradeCost(upgrade)) .. (upgrade.Currency == \"Gems\" and \" G\" or \" $\")\n\t\tsubLabel.Text = upgrade.Description .. \"  (owned \" .. upgrade.Bought .. \")\"\n\tend\n\trefresh()\n\tbuyButton.MouseButton1Click:Connect(function()\n\t\tif trySpend(upgrade.Currency, getUpgradeCost(upgrade)) then   -- if we could pay...\n\t\t\tData[upgrade.Stat] = Data[upgrade.Stat] + upgrade.Amount  -- ...increase the stat (ClickPower or AutoPower)\n\t\t\tupgrade.Bought = upgrade.Bought + 1                       -- ...count the purchase\n\t\t\trefresh()\n\t\t\tupdateUI()\n\t\t\tshowToast(upgrade.Name .. \" UPGRADED!\", COLORS.Green)\n\t\t\tpop(hero.Frame, 1.15)                                     -- hero does a happy boing\n\t\tend\n\tend)\nend\n\nmakeLabel(\"GAMEPASSES\", UDim2.new(1, -16, 0, 40), UDim2.new(0, 0, 0, 0), shopList, COLORS.Pink).ZIndex = 22 -- section title\n\nfor _, pass in ipairs(GAMEPASSES) do                                  -- one row per gamepass\n\tlocal _, buyButton = makeItemRow(shopList, pass.Name, pass.Description, pass.Color, \"R$ BUY\")\n\tbuyButton.MouseButton1Click:Connect(function()\n\t\tif pass.Id == 0 then                                          -- id not set up yet?\n\t\t\tshowToast(\"Put your Gamepass ID in GAMEPASSES!\", COLORS.Red)\n\t\t\treturn                                                    -- stop here\n\t\tend\n\t\tMarketplaceService:PromptGamePassPurchase(player, pass.Id)    -- open the Roblox buy window\n\tend)\nend\n\n-- When a gamepass purchase window closes, check if they bought it\nMarketplaceService.PromptGamePassPurchaseFinished:Connect(function(who, passId, purchased)\n\tif who ~= player or not purchased then return end                -- not us, or they cancelled\n\tfor _, pass in ipairs(GAMEPASSES) do\n\t\tif pass.Id == passId then\n\t\t\tData.OwnsPass[pass.Name] = true                           -- unlock the bonus\n\t\t\tshowToast(\"THANK YOU! \" .. pass.Name .. \" ACTIVE!\", COLORS.Coin)\n\t\tend\n\tend\n\tupdateUI()\nend)\n\n---------------------------------------------------------------------------\n-- EGGS\n---------------------------------------------------------------------------\n\n-- pickRandomCharacter(): weighted random pick using each character's Chance\nlocal function pickRandomCharacter()\n\tlocal total = 0\n\tfor _, character in ipairs(CHARACTERS) do total = total + character.Chance end -- add up all chances (= 100)\n\tlocal roll = math.random() * total                     -- random number between 0 and total, e.g. 73.4\n\tlocal runningTotal = 0\n\tfor _, character in ipairs(CHARACTERS) do              -- walk down the list...\n\t\trunningTotal = runningTotal + character.Chance     -- ...adding each chance as we go (35, 60, 80, 92, 98, 100)\n\t\tif roll <= runningTotal then                       -- the first one where we pass the roll wins\n\t\t\treturn character                               -- e.g. roll 73.4 -> passes at 80 -> Fire Mage!\n\t\tend\n\tend\n\treturn CHARACTERS[1]                                   -- safety backup (should never happen)\nend\n\nlocal hatching = false -- lock so you can't hatch two eggs at once\n\n-- playHatchAnimation(egg, character): the big exciting hatch cutscene\nlocal function playHatchAnimation(egg, character)\n\tlocal overlay = make(\"Frame\", { Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1, ZIndex = 60 }, gui) -- dark cover\n\ttween(overlay, 0.3, { BackgroundTransparency = 0.35 })               -- darken the screen\n\n\t-- Spinning sun rays behind the egg\n\tlocal rays = make(\"Frame\", { Size = UDim2.new(0.9, 0, 0.9, 0), SizeConstraint = Enum.SizeConstraint.RelativeYY, Position = UDim2.new(0.5, 0, 0.5, 0), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1, ZIndex = 61 }, overlay)\n\tfor i = 1, 8 do                                                       -- 8 rays\n\t\tmake(\"Frame\", {\n\t\t\tSize = UDim2.new(0.08, 0, 1, 0), Position = UDim2.new(0.5, 0, 0.5, 0), AnchorPoint = Vector2.new(0.5, 0.5),\n\t\t\tRotation = i * 22.5,                                          -- 8 rays * 22.5 degrees = evenly spread (they're double-sided)\n\t\t\tBackgroundColor3 = RARITY_COLORS[character.Rarity], BackgroundTransparency = 0.5, ZIndex = 61,\n\t\t}, rays)\n\tend\n\trays.Visible = false                                                  -- hidden until the reveal\n\n\t-- The egg itself (an oval)\n\tlocal eggFrame = make(\"Frame\", { Size = UDim2.new(0.22, 0, 0.3, 0), SizeConstraint = Enum.SizeConstraint.RelativeYY, Position = UDim2.new(0.5, 0, 0.5, 0), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = egg.Color, ZIndex = 62 }, overlay)\n\taddCorner(eggFrame, 999)                                              -- rounded = egg shape\n\taddOutline(eggFrame, 6)\n\taddGradient(eggFrame, COLORS.White, egg.Color)\n\tpop(eggFrame, 0.2)                                                    -- grows in from tiny\n\n\t-- Shake faster and faster\n\tfor i = 1, 10 do\n\t\tlocal waitTime = 0.18 - i * 0.014                                 -- each shake is quicker than the last\n\t\ttween(eggFrame, waitTime, { Rotation = (i % 2 == 0) and 15 or -15 })\n\t\ttask.wait(waitTime)\n\tend\n\n\t-- FLASH!\n\tlocal flash = make(\"Frame\", { Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = COLORS.White, ZIndex = 70 }, overlay)\n\ttween(flash, 0.6, { BackgroundTransparency = 1 })                     -- white flash fades away\n\teggFrame:Destroy()                                                    -- the egg is gone\n\n\t-- Reveal the character card\n\trays.Visible = true\n\tlocal spin = TweenInfo.new(4, Enum.EasingStyle.Linear, Enum.EasingDirection.In, -1) -- spin forever\n\tTweenService:Create(rays, spin, { Rotation = 360 }):Play()\n\n\tlocal card = make(\"Frame\", { Size = UDim2.new(0.28, 0, 0.42, 0), SizeConstraint = Enum.SizeConstraint.RelativeYY, Position = UDim2.new(0.5, 0, 0.5, 0), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = COLORS.White, ZIndex = 63 }, overlay)\n\taddCorner(card, 24)\n\taddOutline(card, 6)\n\taddGradient(card, RARITY_COLORS[character.Rarity], RARITY_COLORS[character.Rarity]:Lerp(COLORS.Outline, 0.5))\n\tlocal picture = make(\"ImageLabel\", { Image = \"\", Size = UDim2.new(0.8, 0, 0.55, 0), Position = UDim2.new(0.5, 0, 0.4, 0), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = COLORS.White, BackgroundTransparency = 0.5, ZIndex = 64 }, card) -- blank character image\n\taddCorner(picture, 18)\n\tmakeLabel(character.Rarity, UDim2.new(0.9, 0, 0.12, 0), UDim2.new(0.5, 0, 0.08, 0), card, RARITY_COLORS[character.Rarity]).ZIndex = 65\n\tmakeLabel(character.Name, UDim2.new(0.9, 0, 0.13, 0), UDim2.new(0.5, 0, 0.77, 0), card).ZIndex = 65\n\tmakeLabel(\"+\" .. character.Power .. \" POWER\", UDim2.new(0.7, 0, 0.09, 0), UDim2.new(0.5, 0, 0.9, 0), card, COLORS.Coin).ZIndex = 65\n\tpop(card, 0.1)                                                        -- burst in\n\n\ttask.wait(2.2)                                                        -- let them admire it\n\ttween(getScale(card), 0.3, { Scale = 0 }, Enum.EasingStyle.Back, Enum.EasingDirection.In) -- shrink away\n\ttween(overlay, 0.3, { BackgroundTransparency = 1 })\n\ttask.wait(0.3)\n\toverlay:Destroy()                                                     -- clean up everything\nend\n\n-- the \"YOUR TEAM\" area inside the egg window gets refilled after each hatch\nlocal teamLabel = nil -- will be created below\n\nlocal function refreshTeamLabel()\n\tlocal counts = {}                                                     -- e.g. counts[\"Ninja Kid\"] = 3\n\tfor _, character in ipairs(Data.Team) do\n\t\tcounts[character.Name] = (counts[character.Name] or 0) + 1        -- count each name (\"or 0\" = start at 0 if new)\n\tend\n\tlocal lines = {}\n\tfor _, character in ipairs(CHARACTERS) do                             -- go in rarity order\n\t\tif counts[character.Name] then\n\t\t\ttable.insert(lines, character.Name .. \" x\" .. counts[character.Name]) -- \"Ninja Kid x3\"\n\t\tend\n\tend\n\tteamLabel.Text = #lines > 0 and table.concat(lines, \"   \") or \"No heroes yet... hatch an egg!\" -- glue lines together\nend\n\nfor _, egg in ipairs(EGGS) do                                             -- one row per egg\n\tlocal priceText = formatNumber(egg.Price) .. (egg.Currency == \"Gems\" and \" G\" or \" $\")\n\tlocal description = egg.Rolls > 1 and \"Rolls twice, keeps the BEST!\" or \"A classic egg!\"\n\tlocal _, buyButton = makeItemRow(eggList, egg.Name, description, egg.Color:Lerp(COLORS.Pink, 0.4), priceText)\n\tbuyButton.MouseButton1Click:Connect(function()\n\t\tif hatching then return end                                       -- already hatching? ignore\n\t\tif not trySpend(egg.Currency, egg.Price) then return end          -- can't pay? stop\n\t\thatching = true\n\n\t\tlocal best = pickRandomCharacter()                                -- first roll\n\t\tfor roll = 2, egg.Rolls do                                        -- extra rolls (Golden Egg only - for Basic Egg this loop runs 0 times)\n\t\t\tlocal another = pickRandomCharacter()\n\t\t\tif another.Power > best.Power then best = another end         -- keep the stronger one\n\t\tend\n\n\t\tupdateUI()\n\t\teggPanel.Visible = false                                          -- hide the window during the cutscene\n\t\tplayHatchAnimation(egg, best)                                     -- the big animation (waits until finished)\n\t\ttable.insert(Data.Team, best)                                     -- add to your team\n\t\trefreshTeamLabel()\n\t\tupdateUI()\n\t\tshowToast(\"You got \" .. best.Name .. \"!\", RARITY_COLORS[best.Rarity])\n\t\tpop(teamText, 1.5)\n\t\thatching = false\n\tend)\nend\n\nmakeLabel(\"YOUR TEAM\", UDim2.new(1, -16, 0, 40), UDim2.new(0, 0, 0, 0), eggList, COLORS.Purple).ZIndex = 22\nteamLabel = makeLabel(\"\", UDim2.new(1, -16, 0, 80), UDim2.new(0, 0, 0, 0), eggList, COLORS.Outline)\nteamLabel.Font = TEXT_FONT\nteamLabel.TextWrapped = true\nteamLabel.ZIndex = 22\nteamLabel:FindFirstChildOfClass(\"UIStroke\").Color = COLORS.White          -- dark text, white outline (readable on cream)\nrefreshTeamLabel()\n\n---------------------------------------------------------------------------\n-- STORY\n---------------------------------------------------------------------------\nlocal storyRows = {} -- remember each chapter's row so we can update it\n\nfor index, chapter in ipairs(CHAPTERS) do\n\tlocal firstStage = (index - 1) * STAGES_PER_CHAPTER + 1                  -- chapter 2 starts at stage 11\n\tlocal lastStage = index * STAGES_PER_CHAPTER                             -- chapter 2 ends at stage 20\n\tlocal row, button, subLabel = makeItemRow(storyList, \"CH.\" .. index .. \" \" .. chapter.Name, \"Stages \" .. firstStage .. \"-\" .. lastStage .. \"  |  Boss: \" .. chapter.Boss, chapter.Color, \"\")\n\tbutton.Active = false                                                    -- just a status badge, not clickable\n\tstoryRows[index] = { Row = row, Button = button, First = firstStage, Last = lastStage }\nend\n\nlocal function refreshStory()\n\tfor _, info in pairs(storyRows) do\n\t\tif Data.Stage > info.Last then                                       -- beaten\n\t\t\tinfo.Button.Text = \"CLEARED\"\n\t\t\tinfo.Button.TextColor3 = COLORS.Coin\n\t\telseif Data.Stage >= info.First then                                 -- current\n\t\t\tinfo.Button.Text = \"NOW!\"\n\t\t\tinfo.Button.TextColor3 = COLORS.White\n\t\telse                                                                 -- not reached\n\t\t\tinfo.Button.Text = \"LOCKED\"\n\t\t\tinfo.Button.TextColor3 = Color3.fromRGB(160, 160, 160)\n\t\tend\n\tend\nend\n\n-- Menu buttons open their windows\nshopButton.MouseButton1Click:Connect(function() openPanel(shopPanel) end)\neggsButton.MouseButton1Click:Connect(function() openPanel(eggPanel) end)\nstoryButton.MouseButton1Click:Connect(function()\n\trefreshStory()                                                           -- update before showing\n\topenPanel(storyPanel)\nend)\n\n---------------------------------------------------------------------------\n-- 7. START THE GAME\n---------------------------------------------------------------------------\n\n-- Check which gamepasses the player already owns (pcall = \"try this, don't crash if it fails\")\nfor _, pass in ipairs(GAMEPASSES) do\n\tif pass.Id ~= 0 then                                                     -- only real ids\n\t\tlocal ok, owns = pcall(function()\n\t\t\treturn MarketplaceService:UserOwnsGamePassAsync(player.UserId, pass.Id)\n\t\tend)\n\t\tif ok and owns then Data.OwnsPass[pass.Name] = true end\n\tend\nend\n\nspawnEnemy()                                                                 -- first enemy\nupdateUI()                                                                   -- fill in all the numbers\n\n-- Every frame: spin the background, the attack button rainbow\nRunService.RenderStepped:Connect(function(deltaTime)                         -- deltaTime = seconds since the last frame (about 0.016)\n\tbackgroundGradient.Rotation = (backgroundGradient.Rotation + deltaTime * 15) % 360 -- slow spin (15 degrees/sec)\n\trainbow.Offset = Vector2.new((os.clock() * 0.5) % 2 - 1, 0)              -- slide the rainbow sideways forever\nend)\n\n-- AUTO ATTACK: every second your hero + team hits the enemy by themselves\ntask.spawn(function()                                                        -- run this loop \"on the side\" so it doesn't freeze the script\n\twhile true do                                                            -- loop forever\n\t\ttask.wait(1)                                                         -- wait 1 second\n\t\tif getAutoDamage() > 0 then\n\t\t\theroLunge()\n\t\t\tdamageEnemy(getAutoDamage(), COLORS.Gem)                         -- blue numbers = auto damage\n\t\tend\n\tend\nend)\n" s.Parent=f print("Anime Incremental Game installed! Press PLAY.")